export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly maxRetries: number;
  private readonly pending: Array<() => void> = [];
  private idleWaiters: Array<() => void> = [];
  private running = 0;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    if (!Number.isInteger(maxRetries) || maxRetries < 0) {
      throw new RangeError("maxRetries must be a non-negative integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Number of jobs waiting to start. */
  get size(): number {
    return this.pending.length;
  }

  /** Number of jobs currently running. */
  get active(): number {
    return this.running;
  }

  /**
   * Enqueue a job. The returned promise settles with the job's result, or
   * rejects with its last error once all retries are exhausted.
   */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.runWithRetries(job));
        } catch (err) {
          reject(err);
        } finally {
          this.running--;
          this.next();
        }
      });
      this.next();
    });
  }

  /** Resolves once no jobs are running or waiting. Never rejects. */
  async onIdle(): Promise<void> {
    // Re-check after each wake-up: a job's completion handler may have
    // enqueued more work before we resumed.
    while (this.running > 0 || this.pending.length > 0) {
      await new Promise<void>((resolve) => this.idleWaiters.push(resolve));
    }
  }

  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const start = this.pending.shift()!;
      this.running++;
      start();
    }
    if (this.running === 0 && this.pending.length === 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const wake of waiters) wake();
    }
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { JobQueue } from "./jobQueue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

test("respects the concurrency limit", async () => {
  const queue = new JobQueue(2);
  let active = 0;
  let peak = 0;
  for (let i = 0; i < 10; i++) {
    queue.add(async () => {
      peak = Math.max(peak, ++active);
      await sleep(5);
      active--;
    });
  }
  await queue.onIdle();
  assert.equal(peak, 2);
  assert.equal(queue.active, 0);
  assert.equal(queue.size, 0);
});

test("retries a failing job up to three times, then rejects", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const result = queue.add(async () => {
    calls++;
    throw new Error("boom");
  });
  await assert.rejects(result, /boom/);
  assert.equal(calls, 4);
});

test("resolves if a retry succeeds", async () => {
  const queue = new JobQueue(1);
  let calls = 0;
  const value = await queue.add(async () => {
    if (++calls < 3) throw new Error("flaky");
    return "ok";
  });
  assert.equal(value, "ok");
  assert.equal(calls, 3);
});

test("onIdle waits for jobs added by completion handlers", async () => {
  const queue = new JobQueue(1);
  let secondDone = false;
  queue.add(() => sleep(5)).then(() => {
    queue.add(async () => {
      await sleep(5);
      secondDone = true;
    });
  });
  await queue.onIdle();
  assert.equal(secondDone, true);
});

test("onIdle resolves immediately on an empty queue and survives failures", async () => {
  const queue = new JobQueue(3);
  await queue.onIdle();
  queue.add(() => Promise.reject(new Error("x"))).catch(() => {});
  await queue.onIdle();
  assert.equal(queue.active, 0);
});

